/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
from html.parser import HTMLParser
import re,json
s=Path('index.html').read_text()
class Check(HTMLParser):
 def __init__(self):super().__init__();self.ids=[];self.links=[];self.posts=[]
 def handle_starttag(self,t,attrs):
  a=dict(attrs)
  if 'id' in a:self.ids.append(a['id'])
  if t=='a':self.links.append(a.get('href',''))
  if 'post' in a.get('class','').split():self.posts.append(a['data-tag'])
c=Check();c.feed(s)
assert len(c.ids)==len(set(c.ids))
assert all(h=='#' or h[1:] in c.ids for h in c.links if h.startswith('#'))
assert len(c.posts)==6
assert not re.search(r'<img["'^>]+src="https?://'"',s)
Path('/private/tmp/maya-site-script.js').write_text(s.split('<script>')[-1].split('</script>')[0])
Path('/private/tmp/maya-post-tags.json').write_text(json.dumps(c.posts))
print('HTML checks passed: unique IDs, valid fragment targets, 6 posts, no remote images.')
print('Biography:',len(re.sub('<["'^>]+>'"',' ',s.split('<div class=\"about-bio\">')[1].split('</div>')[0]).split()),'words')
PY
node --check /private/tmp/maya-site-script.js
node <<'JS'
const fs=require('fs'),vm=require('vm'),assert=require('assert');
function el(dataset={}){return {dataset,style:{},attrs:{},listeners:{},setAttribute(k,v){this.attrs[k]=v},addEventListener(k,v){this.listeners[k]=v}}}
const filters=['All','Design','Data','Freelancing','Field notes'].map(x=>el({filter:x}));
const posts=JSON.parse(fs.readFileSync('/private/tmp/maya-post-tags.json')).map(x=>el({tag:x}));
const ids={};for(const id of ['filter-status','detail-dialog','dialog-label','dialog-title','dialog-meta','dialog-body','newsletter-form','newsletter-status'])ids[id]=el();
const theme=el(),meta=el(),close=el(),root=el({theme:'light'}),body=el();
const document={documentElement:root,body,activeElement:null,getElementById:id=>ids[id],querySelector:s=>s==='.theme-toggle'?theme:s==='.dialog-close'?close:meta,querySelectorAll:s=>s==='[data-filter]'?filters:s==='.post'?posts:[]};
const stored={};const localStorage={setItem:(k,v)=>stored[k]=v};
vm.runInNewContext(fs.readFileSync('/private/tmp/maya-site-script.js','utf8'),{document,localStorage});
assert.equal(theme.attrs['aria-label'],'Switch to dark color scheme');
theme.listeners.click();assert.equal(root.dataset.theme,'dark');assert.equal(stored['maya-theme'],'dark');assert.equal(theme.attrs['aria-pressed'],'true');
theme.listeners.click();assert.equal(root.dataset.theme,'light');
for(const f of filters){f.listeners.click();const expected=f.dataset.filter==='All'?6:f.dataset.filter==='Design'||f.dataset.filter==='Field notes'?2:1;assert.equal(posts.filter(p=>"'!p.hidden).length,expected);assert.equal(filters.filter(f=>f.attrs['"'aria-pressed']==='true').length,1)}
let prevented=false;ids['newsletter-form'].listeners.submit({preventDefault(){prevented=true}});assert(prevented);assert(ids['newsletter-status'].textContent.includes('has not been sent or saved'));
console.log('JavaScript checks passed: theme toggles and persists; all five filters return expected counts; newsletter feedback is accurate.');
JS"

